paragraph.math:
$$\begin{array}{l}
  {\left\lbrack \frac{f{(x_{0})} + f{(x_{1})}}{2} \right\rbrack ‍\Delta x + \left\lbrack \frac{f{(x_{1})} + f{(x_{2})}}{2} \right\rbrack ‍\Delta x + \ldots + \left\lbrack \frac{f{(x_{n - 1})} + f{(x_{n})}}{2} \right\rbrack ‍\Delta x} \\
  {\mspace{20mu} = \frac{\Delta x}{2}\left\lbrack {f{(x_{0})} + f{(x_{1})} + f{(x_{1})} + f{(x_{2})} + \ldots + f{(x_{n - 1})} + f{(x_{n})}} \right\rbrack} \\
  {\mspace{20mu} = \frac{\Delta x}{2}\left\lbrack {f{(x_{0})} + 2f{(x_{1})} + 2f{(x_{2})} + \ldots + 2f{(x_{n - 1})} + f{(x_{n})}} \right\rbrack}
  \end{array}$$

$$\begin{array}{l}
  {\frac{\Delta x}{3}\left\lbrack {f\left( x_{0} \right) + 4f\left( x_{1} \right) + f\left( x_{2} \right)} \right\rbrack + \frac{\Delta x}{3}\left\lbrack {f\left( x_{2} \right) + 4f\left( x_{3} \right) + f\left( x_{4} \right)} \right\rbrack + \cdots + \frac{\Delta x}{3}\left\lbrack {f\left( x_{n - 2} \right) + 4f\left( x_{n - 1} \right) + f\left( x_{n} \right)} \right\rbrack} \\
  {\quad = \frac{\Delta x}{3}\left\lbrack {f\left( x_{0} \right) + 4f\left( x_{1} \right) + f\left( x_{2} \right) + f\left( x_{2} \right) + 4f\left( x_{3} \right) + f\left( x_{4} \right) + \cdots + f\left( x_{n - 2} \right) + 4f\left( x_{n - 1} \right) + f\left( x_{n} \right)} \right\rbrack} \\
  {\quad = \frac{\Delta x}{3}\left\lbrack {f\left( x_{0} \right) + 4f\left( x_{1} \right) + 2f\left( x_{2} \right) + 4f\left( x_{3} \right) + 2f\left( x_{4} \right) + \cdots + 4f\left( x_{n - 1} \right) + f\left( x_{n} \right)} \right\rbrack}
  \end{array}$$
